<!doctype html><html><head><title>General Ledger</title><style>body{font-family:Arial;margin:30px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #ddd;padding:7px;text-align:left}th{background:#eee}.num{text-align:right}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>General Ledger</h1><p><strong>{{ $account->code }} — {{ $account->name }}</strong><br>Period: {{ $query->from?->format('d M Y') ?? 'Beginning' }} to {{ $query->to?->format('d M Y') ?? 'Current' }}</p><table><thead><tr><th>Date</th><th>Entry</th><th>Description</th><th>Debit</th><th>Credit</th><th>Running</th></tr></thead><tbody>@foreach($lines as $line)<tr><td>{{ \Carbon\Carbon::parse($line->entry_date)->format('d/m/Y') }}</td><td>{{ $line->number }}</td><td>{{ $line->description }}</td><td class="num">{{ number_format((float) $line->debit,2) }}</td><td class="num">{{ number_format((float) $line->credit,2) }}</td><td class="num">{{ number_format((float) $line->running_balance,2) }}</td></tr>@endforeach</tbody></table><p><strong>Closing balance: {{ number_format((float) $balance,2) }}</strong></p></body></html>
